class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        int n = s.size();
        vector<char> dp(n + 1, 0);
        dp[0] = 1;                         // empty prefix is reachable
        int maxLen = 0;
        for (const string& w : wordDict) maxLen = max(maxLen, (int)w.size());

        for (int i = 0; i < n; ++i) {
            if (!dp[i]) continue;
            // try every possible length up to maxLen
            for (int len = 1; len <= maxLen && i + len <= n; ++len) {
                if (dict.find(s.substr(i, len)) != dict.end())
                    dp[i + len] = 1;
            }
        }
        return dp[n];
    }
};
